-- =============================================================================
-- Fisiocloud — script ÚNICO de base de datos
-- Incluye: creación de BDs (antes create_databases.sql) + tablas + seeds +
--          catálogos del sistema anterior (tipos, localidades, DX CIE-10, CUPS).
-- Independiente del entrypoint Docker (infraestructura ≠ instalación de app).
--
-- Uso:
--   sudo mysql -u root -p < fisiocloud_init.sql
--   # Docker:
--   mysql -u root -proot < /app/scripts/fisiocloud_init.sql
--
-- Tras este script NO necesitas:
--   - python manage.py seed_*
--   - python migrate_catalogos_legado.py
--   - migrate (usa --fake si corres migrate después)
-- =============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- -----------------------------------------------------------------------------
-- Bases vacías + privilegios (equivalente al antiguo create_databases.sql)
-- -----------------------------------------------------------------------------
CREATE DATABASE IF NOT EXISTS fisiocloud_seguridad
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE DATABASE IF NOT EXISTS fisiocloud_suscripcion
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE DATABASE IF NOT EXISTS fisiocloud_info_medica
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE DATABASE IF NOT EXISTS fisiocloud_agendamiento
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE DATABASE IF NOT EXISTS fisiocloud_parametrizacion
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE DATABASE IF NOT EXISTS fisiocloud_tratamiento_casa
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE DATABASE IF NOT EXISTS fisiocloud_soporte
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE DATABASE IF NOT EXISTS fisiocloud_procesos_automaticos
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE DATABASE IF NOT EXISTS fisiocloud_asistente_voz
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE USER IF NOT EXISTS 'fisiocloud'@'localhost' IDENTIFIED BY 'CAMBIAR_PASSWORD_FUERTE';
GRANT ALL PRIVILEGES ON fisiocloud_seguridad.* TO 'fisiocloud'@'localhost';
GRANT ALL PRIVILEGES ON fisiocloud_suscripcion.* TO 'fisiocloud'@'localhost';
GRANT ALL PRIVILEGES ON fisiocloud_info_medica.* TO 'fisiocloud'@'localhost';
GRANT ALL PRIVILEGES ON fisiocloud_agendamiento.* TO 'fisiocloud'@'localhost';
GRANT ALL PRIVILEGES ON fisiocloud_parametrizacion.* TO 'fisiocloud'@'localhost';
GRANT ALL PRIVILEGES ON fisiocloud_tratamiento_casa.* TO 'fisiocloud'@'localhost';
GRANT ALL PRIVILEGES ON fisiocloud_soporte.* TO 'fisiocloud'@'localhost';
GRANT ALL PRIVILEGES ON fisiocloud_procesos_automaticos.* TO 'fisiocloud'@'localhost';
GRANT ALL PRIVILEGES ON fisiocloud_asistente_voz.* TO 'fisiocloud'@'localhost';
GRANT ALL PRIVILEGES ON fisiocloud_seguridad.* TO 'root'@'%';
GRANT ALL PRIVILEGES ON fisiocloud_suscripcion.* TO 'root'@'%';
GRANT ALL PRIVILEGES ON fisiocloud_info_medica.* TO 'root'@'%';
GRANT ALL PRIVILEGES ON fisiocloud_agendamiento.* TO 'root'@'%';
GRANT ALL PRIVILEGES ON fisiocloud_parametrizacion.* TO 'root'@'%';
GRANT ALL PRIVILEGES ON fisiocloud_tratamiento_casa.* TO 'root'@'%';
GRANT ALL PRIVILEGES ON fisiocloud_soporte.* TO 'root'@'%';
GRANT ALL PRIVILEGES ON fisiocloud_procesos_automaticos.* TO 'root'@'%';
GRANT ALL PRIVILEGES ON fisiocloud_asistente_voz.* TO 'root'@'%';
FLUSH PRIVILEGES;

-- =============================================================================
-- 1) backend_seguridad → fisiocloud_seguridad
-- =============================================================================

USE fisiocloud_seguridad;

CREATE TABLE IF NOT EXISTS usuarios (
  password VARCHAR(128) NOT NULL,
  last_login DATETIME(6) NULL,
  is_superuser TINYINT(1) NOT NULL DEFAULT 0,
  tipo_documento VARCHAR(10) NOT NULL DEFAULT 'CC',
  doc_usuario VARCHAR(20) NOT NULL PRIMARY KEY,
  nombre VARCHAR(80) NOT NULL,
  apellido VARCHAR(80) NOT NULL,
  email VARCHAR(254) NOT NULL,
  telefono VARCHAR(30) NOT NULL DEFAULT '',
  rol VARCHAR(20) NOT NULL DEFAULT 'TERAPEUTA',
  firma VARCHAR(100) NULL,
  email_verificado TINYINT(1) NOT NULL DEFAULT 0,
  pending_plan_codigo VARCHAR(40) NOT NULL DEFAULT '',
  pending_segmento VARCHAR(40) NOT NULL DEFAULT '',
  activo TINYINT(1) NOT NULL DEFAULT 1,
  is_staff TINYINT(1) NOT NULL DEFAULT 0,
  fecha_creacion DATETIME(6) NOT NULL,
  fecha_actualizacion DATETIME(6) NOT NULL,
  UNIQUE KEY usuarios_email_uniq (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tablet (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  usuario_id VARCHAR(20) NOT NULL,
  identificador VARCHAR(100) NOT NULL,
  descripcion VARCHAR(200) NOT NULL DEFAULT '',
  activo TINYINT(1) NOT NULL DEFAULT 1,
  creado DATETIME(6) NOT NULL,
  UNIQUE KEY tablet_usuario_identificador_uniq (usuario_id, identificador),
  CONSTRAINT fk_tablet_usuario
    FOREIGN KEY (usuario_id) REFERENCES usuarios(doc_usuario) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sistema_config (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  otp_login_habilitado TINYINT(1) NOT NULL DEFAULT 0,
  actualizado DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS auth_tokens (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  usuario_id VARCHAR(20) NOT NULL,
  tipo VARCHAR(20) NOT NULL,
  token VARCHAR(64) NOT NULL,
  expires_at DATETIME(6) NOT NULL,
  usado_en DATETIME(6) NULL,
  creado DATETIME(6) NOT NULL,
  UNIQUE KEY auth_tokens_token_uniq (token),
  KEY auth_tokens_tipo (tipo),
  KEY auth_tokens_token (token),
  CONSTRAINT fk_auth_tokens_usuario
    FOREIGN KEY (usuario_id) REFERENCES usuarios(doc_usuario) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS django_migrations (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  app VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL,
  applied DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT 1, 0, UTC_TIMESTAMP(6)
WHERE NOT EXISTS (SELECT 1 FROM sistema_config WHERE id = 1);

SELECT 'core', '0001_initial', UTC_TIMESTAMP(6)
WHERE NOT EXISTS (SELECT 1 FROM django_migrations WHERE app='core' AND name='0001_initial');
SELECT 'core', '0002_usuario_tipo_documento_alter_usuario_rol', UTC_TIMESTAMP(6)
WHERE NOT EXISTS (SELECT 1 FROM django_migrations WHERE app='core' AND name='0002_usuario_tipo_documento_alter_usuario_rol');
SELECT 'core', '0003_remove_roles_admision_coordinador', UTC_TIMESTAMP(6)
WHERE NOT EXISTS (SELECT 1 FROM django_migrations WHERE app='core' AND name='0003_remove_roles_admision_coordinador');
SELECT 'core', '0004_usuario_firma', UTC_TIMESTAMP(6)
WHERE NOT EXISTS (SELECT 1 FROM django_migrations WHERE app='core' AND name='0004_usuario_firma');
SELECT 'core', '0005_auth_email_otp', UTC_TIMESTAMP(6)
WHERE NOT EXISTS (SELECT 1 FROM django_migrations WHERE app='core' AND name='0005_auth_email_otp');

SELECT 'fisiocloud_seguridad OK' AS etapa,
       (SELECT COUNT(*) FROM usuarios) AS usuarios,
       (SELECT COUNT(*) FROM sistema_config) AS sistema_config;



-- #############################################################################
-- Continuación consolidada desde schema_seed_suscripcion.sql
-- #############################################################################

-- =============================================================================
-- Fisiocloud — backend_suscripcion
-- Script SQL completo: BD + tablas + datos iniciales (planes/features/tarifas)
-- Equivale a: migrate + seed_planes  (sin usar manage.py)
--
-- Uso:
--   sudo mysql -u root -p < schema_seed_suscripcion.sql
--   o dentro de mysql:  SOURCE /ruta/schema_seed_suscripcion.sql;
--
-- Si más adelante corres `python manage.py migrate`, usa:
--   python manage.py migrate --fake
-- (porque las tablas de core ya existen y están marcadas abajo).
-- =============================================================================

CREATE DATABASE IF NOT EXISTS fisiocloud_suscripcion
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

-- Usuario app (si ya existe desde seguridad, el GRANT basta)
GRANT ALL PRIVILEGES ON fisiocloud_suscripcion.* TO 'fisiocloud'@'localhost';
FLUSH PRIVILEGES;

USE fisiocloud_suscripcion;

-- -----------------------------------------------------------------------------
-- Tablas de negocio (estado final tras migraciones 0001 + 0002)
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS features (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  codigo VARCHAR(50) NOT NULL UNIQUE,
  nombre VARCHAR(100) NOT NULL,
  descripcion LONGTEXT NOT NULL,
  activo TINYINT(1) NOT NULL DEFAULT 1,
  icono VARCHAR(80) NOT NULL DEFAULT 'fas fa-star',
  orden SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  ruta_web VARCHAR(80) NOT NULL DEFAULT '',
  ruta_app VARCHAR(120) NOT NULL DEFAULT '',
  mostrar_menu TINYINT(1) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS planes (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  codigo VARCHAR(40) NOT NULL UNIQUE,
  nombre VARCHAR(100) NOT NULL,
  descripcion LONGTEXT NOT NULL,
  dias_duracion INT UNSIGNED NOT NULL,
  activo TINYINT(1) NOT NULL DEFAULT 1,
  orden SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  destacado TINYINT(1) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS plan_tarifas (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  segmento VARCHAR(50) NOT NULL DEFAULT 'GENERAL',
  moneda VARCHAR(3) NOT NULL DEFAULT 'COP',
  precio DECIMAL(12,2) NOT NULL,
  vigencia_desde DATE NOT NULL,
  vigencia_hasta DATE NULL,
  activo TINYINT(1) NOT NULL DEFAULT 1,
  plan_id BIGINT NOT NULL,
  CONSTRAINT fk_plan_tarifas_plan
    FOREIGN KEY (plan_id) REFERENCES planes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS plan_features (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  habilitado TINYINT(1) NOT NULL DEFAULT 1,
  feature_id BIGINT NOT NULL,
  plan_id BIGINT NOT NULL,
  UNIQUE KEY plan_features_plan_feature_uniq (plan_id, feature_id),
  CONSTRAINT fk_plan_features_feature
    FOREIGN KEY (feature_id) REFERENCES features(id) ON DELETE CASCADE,
  CONSTRAINT fk_plan_features_plan
    FOREIGN KEY (plan_id) REFERENCES planes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS suscripciones (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  usuario_doc VARCHAR(20) NOT NULL,
  estado VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE',
  fecha_inicio DATETIME(6) NULL,
  fecha_fin DATETIME(6) NULL,
  creado DATETIME(6) NOT NULL,
  actualizado DATETIME(6) NOT NULL,
  plan_id BIGINT NOT NULL,
  tarifa_id BIGINT NULL,
  KEY suscripciones_usuario_doc (usuario_doc),
  CONSTRAINT fk_suscripciones_plan
    FOREIGN KEY (plan_id) REFERENCES planes(id) ON DELETE RESTRICT,
  CONSTRAINT fk_suscripciones_tarifa
    FOREIGN KEY (tarifa_id) REFERENCES plan_tarifas(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS pagos_suscripcion (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  referencia VARCHAR(64) NOT NULL UNIQUE,
  monto DECIMAL(12,2) NOT NULL,
  moneda VARCHAR(3) NOT NULL DEFAULT 'COP',
  estado VARCHAR(20) NOT NULL DEFAULT 'CREADO',
  pasarela VARCHAR(40) NOT NULL DEFAULT 'SIMULADA',
  pasarela_payment_id VARCHAR(64) NOT NULL DEFAULT '',
  checkout_url VARCHAR(500) NOT NULL DEFAULT '',
  raw_response JSON NOT NULL,
  creado DATETIME(6) NOT NULL,
  pagado_en DATETIME(6) NULL,
  suscripcion_id BIGINT NOT NULL,
  CONSTRAINT fk_pagos_suscripcion
    FOREIGN KEY (suscripcion_id) REFERENCES suscripciones(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Control de migraciones Django (para que un migrate futuro no intente recrear core)
CREATE TABLE IF NOT EXISTS django_migrations (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  app VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL,
  applied DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT 'core', '0001_initial', UTC_TIMESTAMP(6)
WHERE NOT EXISTS (
  SELECT 1 FROM django_migrations WHERE app='core' AND name='0001_initial'
);

SELECT 'core', '0002_feature_menu_plan_destacado', UTC_TIMESTAMP(6)
WHERE NOT EXISTS (
  SELECT 1 FROM django_migrations WHERE app='core' AND name='0002_feature_menu_plan_destacado'
);

-- -----------------------------------------------------------------------------
-- Datos iniciales (= seed_planes)
-- -----------------------------------------------------------------------------

ON DUPLICATE KEY UPDATE
  nombre=VALUES(nombre),
  descripcion=VALUES(descripcion),
  activo=VALUES(activo),
  icono=VALUES(icono),
  orden=VALUES(orden),
  ruta_web=VALUES(ruta_web),
  ruta_app=VALUES(ruta_app),
  mostrar_menu=VALUES(mostrar_menu);

ON DUPLICATE KEY UPDATE
  nombre=VALUES(nombre),
  descripcion=VALUES(descripcion),
  dias_duracion=VALUES(dias_duracion),
  activo=VALUES(activo),
  orden=VALUES(orden),
  destacado=VALUES(destacado);

-- Plan ↔ Feature (MENSUAL)
SELECT p.id, f.id, 1
FROM planes p
JOIN features f ON f.codigo IN ('agenda','pacientes','valoraciones','evoluciones','consentimiento')
WHERE p.codigo = 'MENSUAL'
ON DUPLICATE KEY UPDATE habilitado=1;

-- Plan ↔ Feature (SEMESTRAL)
SELECT p.id, f.id, 1
FROM planes p
JOIN features f ON f.codigo IN (
  'agenda','pacientes','valoraciones','evoluciones','facturacion',
  'tratamiento_casa','app_movil','recordatorio_agenda','consentimiento','asistente_voz'
)
WHERE p.codigo = 'SEMESTRAL'
ON DUPLICATE KEY UPDATE habilitado=1;

-- Plan ↔ Feature (ANUAL)
SELECT p.id, f.id, 1
FROM planes p
JOIN features f ON f.codigo IN (
  'agenda','pacientes','valoraciones','evoluciones','facturacion','reportes_rips',
  'tratamiento_casa','app_movil','multi_terapeuta','recordatorio_agenda',
  'envio_hc_fin','consentimiento','asistente_voz'
)
WHERE p.codigo = 'ANUAL'
ON DUPLICATE KEY UPDATE habilitado=1;

-- Tarifas GENERAL
SELECT p.id, 'GENERAL', 'COP',
  CASE p.codigo
    WHEN 'MENSUAL' THEN 89000.00
    WHEN 'SEMESTRAL' THEN 449000.00
    WHEN 'ANUAL' THEN 790000.00
  END,
  '2024-01-01', NULL, 1
FROM planes p
WHERE p.codigo IN ('MENSUAL','SEMESTRAL','ANUAL')
  AND NOT EXISTS (
    SELECT 1 FROM plan_tarifas t
    WHERE t.plan_id = p.id AND t.segmento='GENERAL' AND t.vigencia_desde='2024-01-01'
  );

-- Tarifas PROMO
SELECT p.id, 'PROMO', 'COP',
  CASE p.codigo
    WHEN 'MENSUAL' THEN 69000.00
    WHEN 'SEMESTRAL' THEN 399000.00
    WHEN 'ANUAL' THEN 690000.00
  END,
  '2024-01-01', NULL, 1
FROM planes p
WHERE p.codigo IN ('MENSUAL','SEMESTRAL','ANUAL')
  AND NOT EXISTS (
    SELECT 1 FROM plan_tarifas t
    WHERE t.plan_id = p.id AND t.segmento='PROMO' AND t.vigencia_desde='2024-01-01'
  );

-- Verificación
SELECT 'planes' AS tabla, COUNT(*) AS n FROM planes
UNION ALL SELECT 'features', COUNT(*) FROM features
UNION ALL SELECT 'plan_features', COUNT(*) FROM plan_features
UNION ALL SELECT 'plan_tarifas', COUNT(*) FROM plan_tarifas;


-- #############################################################################
-- Continuación consolidada desde schema_seed_agendamiento.sql
-- #############################################################################

-- =============================================================================
-- Fisiocloud — backend_agendamiento
-- BD + tablas + datos iniciales (tipos de terapia + terapeuta de prueba)
-- Equivale a migrate (+ seed mínimo). No requiere manage.py.
--
-- Uso:
--   sudo mysql -u root -p < schema_seed_agendamiento.sql
--
-- Si luego usas migrate:
--   python manage.py migrate --fake
-- =============================================================================

CREATE DATABASE IF NOT EXISTS fisiocloud_agendamiento
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

GRANT ALL PRIVILEGES ON fisiocloud_agendamiento.* TO 'fisiocloud'@'localhost';
FLUSH PRIVILEGES;

USE fisiocloud_agendamiento;

-- -----------------------------------------------------------------------------
-- Tablas (estado final: migraciones 0001 + 0002 + 0003)
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS fisioterapeutas (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  documento VARCHAR(20) NOT NULL UNIQUE,
  nombre VARCHAR(80) NOT NULL,
  apellido VARCHAR(80) NOT NULL,
  telefono VARCHAR(30) NOT NULL DEFAULT '',
  email VARCHAR(254) NOT NULL DEFAULT '',
  activo TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tipo_terapia (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  nombre VARCHAR(80) NOT NULL,
  duracion_minutos INT UNSIGNED NOT NULL DEFAULT 45,
  activo TINYINT(1) NOT NULL DEFAULT 1,
  parametrizacion_id INT UNSIGNED NULL,
  KEY tipo_terapia_parametrizacion_id (parametrizacion_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS fisio_tipo (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  fisioterapeuta_id BIGINT NOT NULL,
  tipo_terapia_id BIGINT NOT NULL,
  activo TINYINT(1) NOT NULL DEFAULT 1,
  tarifa_valoracion DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  tarifa_evolucion DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  duracion_valoracion_minutos INT UNSIGNED NOT NULL DEFAULT 60,
  duracion_evolucion_minutos INT UNSIGNED NOT NULL DEFAULT 45,
  UNIQUE KEY fisio_tipo_fisio_tipo_uniq (fisioterapeuta_id, tipo_terapia_id),
  CONSTRAINT fk_fisio_tipo_fisio
    FOREIGN KEY (fisioterapeuta_id) REFERENCES fisioterapeutas(id) ON DELETE CASCADE,
  CONSTRAINT fk_fisio_tipo_tipo
    FOREIGN KEY (tipo_terapia_id) REFERENCES tipo_terapia(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS bloqueo_dia_terapeuta (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  dia DATE NOT NULL,
  motivo VARCHAR(200) NOT NULL DEFAULT '',
  fisioterapeuta_id BIGINT NOT NULL,
  UNIQUE KEY bloqueo_fisio_dia_uniq (fisioterapeuta_id, dia),
  CONSTRAINT fk_bloqueo_fisio
    FOREIGN KEY (fisioterapeuta_id) REFERENCES fisioterapeutas(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS calendario (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  documento_paciente VARCHAR(20) NOT NULL,
  primera_vez VARCHAR(1) NOT NULL DEFAULT 'N',
  proposito VARCHAR(12) NOT NULL DEFAULT 'EVOLUCION',
  inicio_cita DATETIME(6) NOT NULL,
  fin_cita DATETIME(6) NOT NULL,
  estado VARCHAR(1) NOT NULL DEFAULT 'P',
  creado DATETIME(6) NOT NULL,
  modificado DATETIME(6) NOT NULL,
  creado_por VARCHAR(20) NOT NULL DEFAULT '',
  fisioterapeuta_id BIGINT NULL,
  tipo_terapia_id BIGINT NULL,
  KEY calendario_documento_paciente (documento_paciente),
  KEY calendario_inicio (inicio_cita),
  CONSTRAINT fk_calendario_fisio
    FOREIGN KEY (fisioterapeuta_id) REFERENCES fisioterapeutas(id) ON DELETE RESTRICT,
  CONSTRAINT fk_calendario_tipo
    FOREIGN KEY (tipo_terapia_id) REFERENCES tipo_terapia(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS django_migrations (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  app VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL,
  applied DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT 'core', '0001_initial', UTC_TIMESTAMP(6)
WHERE NOT EXISTS (SELECT 1 FROM django_migrations WHERE app='core' AND name='0001_initial');

SELECT 'core', '0002_cita_proposito', UTC_TIMESTAMP(6)
WHERE NOT EXISTS (SELECT 1 FROM django_migrations WHERE app='core' AND name='0002_cita_proposito');

SELECT 'core', '0003_fisio_tarifas_duraciones', UTC_TIMESTAMP(6)
WHERE NOT EXISTS (SELECT 1 FROM django_migrations WHERE app='core' AND name='0003_fisio_tarifas_duraciones');

-- -----------------------------------------------------------------------------
-- Datos iniciales: tipos de terapia (alineados al seed de parametrización)
-- parametrizacion_id = 1..6 asume el orden típico al sembrar parametrización
-- -----------------------------------------------------------------------------

ON DUPLICATE KEY UPDATE
  nombre=VALUES(nombre),
  duracion_minutos=VALUES(duracion_minutos),
  activo=VALUES(activo),
  parametrizacion_id=VALUES(parametrizacion_id);

-- Terapeuta de prueba (mismo doc/email del admin creado en seguridad)
VALUES ('10000001', 'Admin', 'Prueba', '', 'admin@prueba.com', 1)
ON DUPLICATE KEY UPDATE
  nombre=VALUES(nombre),
  apellido=VALUES(apellido),
  email=VALUES(email),
  activo=1;

-- Asocia todos los tipos al terapeuta de prueba (tarifas ejemplo COP)
  fisioterapeuta_id, tipo_terapia_id, activo,
  tarifa_valoracion, tarifa_evolucion,
  duracion_valoracion_minutos, duracion_evolucion_minutos
)
SELECT f.id, t.id, 1,
  CASE t.nombre WHEN 'Valoración' THEN 80000.00 ELSE 60000.00 END,
  CASE t.nombre WHEN 'Valoración' THEN 80000.00 ELSE 45000.00 END,
  CASE t.nombre WHEN 'Valoración' THEN 60 ELSE 60 END,
  CASE t.nombre WHEN 'Valoración' THEN 60 ELSE 45 END
FROM fisioterapeutas f
CROSS JOIN tipo_terapia t
WHERE f.documento = '10000001'
  AND t.activo = 1
ON DUPLICATE KEY UPDATE
  activo=1,
  tarifa_valoracion=VALUES(tarifa_valoracion),
  tarifa_evolucion=VALUES(tarifa_evolucion),
  duracion_valoracion_minutos=VALUES(duracion_valoracion_minutos),
  duracion_evolucion_minutos=VALUES(duracion_evolucion_minutos);

-- Verificación
SELECT 'fisioterapeutas' AS tabla, COUNT(*) AS n FROM fisioterapeutas
UNION ALL SELECT 'tipo_terapia', COUNT(*) FROM tipo_terapia
UNION ALL SELECT 'fisio_tipo', COUNT(*) FROM fisio_tipo
UNION ALL SELECT 'calendario', COUNT(*) FROM calendario;


-- #############################################################################
-- Continuación consolidada desde schema_seed_info_medica.sql
-- #############################################################################

-- =============================================================================
-- Fisiocloud — backend_info_medica
-- BD + tablas (estado final migraciones 0001–0009) + paciente de prueba
--
-- Uso:
--   sudo mysql -u root -p < schema_seed_info_medica.sql
--
-- Si luego usas migrate:
--   python manage.py migrate --fake
-- =============================================================================

CREATE DATABASE IF NOT EXISTS fisiocloud_info_medica
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

GRANT ALL PRIVILEGES ON fisiocloud_info_medica.* TO 'fisiocloud'@'localhost';
FLUSH PRIVILEGES;

USE fisiocloud_info_medica;

-- -----------------------------------------------------------------------------
-- Pacientes
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pacientes (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  terapeuta_doc VARCHAR(20) NOT NULL DEFAULT '',
  documento VARCHAR(20) NOT NULL,
  tipo_documento VARCHAR(10) NOT NULL DEFAULT 'CC',
  nombres VARCHAR(100) NOT NULL,
  primer_apellido VARCHAR(80) NOT NULL DEFAULT '',
  segundo_apellido VARCHAR(80) NOT NULL DEFAULT '',
  apellidos VARCHAR(100) NOT NULL DEFAULT '',
  fecha_nacimiento DATE NULL,
  sexo VARCHAR(10) NOT NULL DEFAULT '',
  telefono VARCHAR(30) NOT NULL DEFAULT '',
  email VARCHAR(254) NOT NULL DEFAULT '',
  nacionalidad VARCHAR(40) NOT NULL DEFAULT 'Colombia',
  categoria VARCHAR(5) NOT NULL DEFAULT '',
  plan VARCHAR(80) NOT NULL DEFAULT '',
  cot_ben VARCHAR(30) NOT NULL DEFAULT '',
  clasificacion VARCHAR(40) NOT NULL DEFAULT '',
  incapacidad VARCHAR(20) NOT NULL DEFAULT '',
  datos_basicos_completos TINYINT(1) NOT NULL DEFAULT 0,
  activo TINYINT(1) NOT NULL DEFAULT 1,
  creado DATETIME(6) NOT NULL,
  actualizado DATETIME(6) NOT NULL,
  UNIQUE KEY pacientes_terapeuta_documento_uniq (terapeuta_doc, documento),
  KEY pacientes_terapeuta_doc (terapeuta_doc),
  KEY pacientes_documento (documento),
  KEY pacientes_terapeuta_documento_idx (terapeuta_doc, documento)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS informacion (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  paciente_id BIGINT NOT NULL UNIQUE,
  entidad VARCHAR(80) NOT NULL DEFAULT '',
  tipo_vinculacion VARCHAR(80) NOT NULL DEFAULT '',
  no_autorizacion VARCHAR(40) NOT NULL DEFAULT '',
  ocupacion VARCHAR(100) NOT NULL DEFAULT '',
  estado_civil VARCHAR(40) NOT NULL DEFAULT '',
  localidad VARCHAR(80) NOT NULL DEFAULT '',
  barrio VARCHAR(100) NOT NULL DEFAULT '',
  direccion VARCHAR(200) NOT NULL DEFAULT '',
  telefono VARCHAR(30) NOT NULL DEFAULT '',
  celular VARCHAR(30) NOT NULL DEFAULT '',
  email VARCHAR(254) NOT NULL DEFAULT '',
  acudiente VARCHAR(120) NOT NULL DEFAULT '',
  parentesco VARCHAR(60) NOT NULL DEFAULT '',
  telefono_acudiente VARCHAR(30) NOT NULL DEFAULT '',
  actualizado DATETIME(6) NOT NULL,
  CONSTRAINT fk_informacion_paciente
    FOREIGN KEY (paciente_id) REFERENCES pacientes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS antecedentes (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  paciente_id BIGINT NOT NULL UNIQUE,
  enfermedades LONGTEXT NOT NULL,
  traumas LONGTEXT NOT NULL,
  cirugias LONGTEXT NOT NULL,
  protesis LONGTEXT NOT NULL,
  alergias LONGTEXT NOT NULL,
  h_familiar LONGTEXT NOT NULL,
  h_ocupacional LONGTEXT NOT NULL,
  marcapasos VARCHAR(2) NOT NULL DEFAULT 'NO',
  medicamentos LONGTEXT NOT NULL,
  traumaticos LONGTEXT NOT NULL,
  hospitalarios LONGTEXT NOT NULL,
  otros LONGTEXT NOT NULL,
  observaciones LONGTEXT NOT NULL,
  dis_agua TINYINT(1) NOT NULL DEFAULT 0,
  dis_luz TINYINT(1) NOT NULL DEFAULT 0,
  dis_alcantarillado TINYINT(1) NOT NULL DEFAULT 0,
  dis_ser_sani TINYINT(1) NOT NULL DEFAULT 0,
  vias_acceso VARCHAR(100) NOT NULL DEFAULT '',
  cd_entor_domestico TINYINT(1) NOT NULL DEFAULT 0,
  cd_acum_suciedad TINYINT(1) NOT NULL DEFAULT 0,
  cd_olores_fet TINYINT(1) NOT NULL DEFAULT 0,
  cd_temp_domes TINYINT(1) NOT NULL DEFAULT 0,
  cd_pres_insec TINYINT(1) NOT NULL DEFAULT 0,
  registro DATE NULL,
  diligenciado TINYINT(1) NOT NULL DEFAULT 0,
  actualizado DATETIME(6) NOT NULL,
  CONSTRAINT fk_antecedentes_paciente
    FOREIGN KEY (paciente_id) REFERENCES pacientes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS orden_medica (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  paciente_id BIGINT NOT NULL,
  numero_autorizacion VARCHAR(40) NOT NULL DEFAULT '',
  fecha_orden DATE NOT NULL,
  fecha_vencimiento DATE NULL,
  sesiones_autorizadas INT UNSIGNED NOT NULL DEFAULT 10,
  tipo_terapia VARCHAR(80) NOT NULL DEFAULT '',
  dx_principal VARCHAR(10) NOT NULL DEFAULT '',
  archivo VARCHAR(100) NULL,
  estado VARCHAR(20) NOT NULL DEFAULT 'ACTIVA',
  creado_por VARCHAR(20) NOT NULL DEFAULT '',
  creado DATETIME(6) NOT NULL,
  CONSTRAINT fk_orden_paciente
    FOREIGN KEY (paciente_id) REFERENCES pacientes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS valoraciones (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  paciente_id BIGINT NOT NULL,
  tipo VARCHAR(20) NOT NULL,
  fecha DATETIME(6) NOT NULL,
  no_autorizacion VARCHAR(40) NOT NULL DEFAULT '',
  dx_principal VARCHAR(10) NOT NULL DEFAULT '',
  dx_relacionado VARCHAR(10) NOT NULL DEFAULT '',
  diagnostico LONGTEXT NOT NULL,
  ambito VARCHAR(20) NOT NULL DEFAULT 'DOMICILIARIO',
  acompanante VARCHAR(100) NOT NULL DEFAULT '',
  medico VARCHAR(100) NOT NULL DEFAULT '',
  cups VARCHAR(20) NOT NULL DEFAULT '',
  numero_sesiones INT UNSIGNED NOT NULL DEFAULT 10,
  sesiones_usadas INT UNSIGNED NOT NULL DEFAULT 0,
  estado VARCHAR(20) NOT NULL DEFAULT 'ACTIVA',
  datos_clinicos JSON NOT NULL,
  plan LONGTEXT NOT NULL,
  observaciones LONGTEXT NOT NULL,
  fac VARCHAR(20) NOT NULL DEFAULT '',
  grado_discapacidad VARCHAR(20) NOT NULL DEFAULT '',
  terapeuta_doc VARCHAR(20) NOT NULL DEFAULT '',
  cita_id INT UNSIGNED NULL,
  creado DATETIME(6) NOT NULL,
  KEY valoraciones_cita_id (cita_id),
  UNIQUE KEY uniq_valoracion_por_cita (cita_id),
  CONSTRAINT fk_valoraciones_paciente
    FOREIGN KEY (paciente_id) REFERENCES pacientes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS evoluciones (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  paciente_id BIGINT NOT NULL,
  valoracion_id BIGINT NULL,
  fecha DATETIME(6) NOT NULL,
  numero_sesion SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  acompanante VARCHAR(100) NOT NULL DEFAULT '',
  temperatura VARCHAR(15) NOT NULL DEFAULT '',
  procedimiento LONGTEXT NOT NULL,
  aclaratoria LONGTEXT NOT NULL,
  ambito VARCHAR(20) NOT NULL DEFAULT 'DOMICILIARIO',
  cups VARCHAR(20) NOT NULL DEFAULT '',
  tipo_terapia VARCHAR(80) NOT NULL DEFAULT '',
  obj_terapeutico TINYINT(1) NOT NULL DEFAULT 0,
  capacitacion TINYINT(1) NOT NULL DEFAULT 0,
  entrenamiento_cuidador TINYINT(1) NOT NULL DEFAULT 0,
  discapacidad VARCHAR(20) NOT NULL DEFAULT '',
  fac VARCHAR(20) NOT NULL DEFAULT '',
  nota_cierre LONGTEXT NOT NULL,
  es_ultima TINYINT(1) NOT NULL DEFAULT 0,
  terapeuta_doc VARCHAR(20) NOT NULL DEFAULT '',
  cita_id INT UNSIGNED NULL,
  adjunto_plan_casero VARCHAR(100) NULL,
  creado DATETIME(6) NOT NULL,
  KEY evoluciones_cita_id (cita_id),
  UNIQUE KEY uniq_evolucion_por_cita (cita_id),
  CONSTRAINT fk_evoluciones_paciente
    FOREIGN KEY (paciente_id) REFERENCES pacientes(id) ON DELETE CASCADE,
  CONSTRAINT fk_evoluciones_valoracion
    FOREIGN KEY (valoracion_id) REFERENCES valoraciones(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS inasistencias (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  paciente_id BIGINT NOT NULL,
  fecha DATE NOT NULL,
  tipo_terapia VARCHAR(80) NOT NULL DEFAULT '',
  motivo LONGTEXT NOT NULL,
  orden_id BIGINT NULL,
  registrado_por VARCHAR(20) NOT NULL DEFAULT '',
  creado DATETIME(6) NOT NULL,
  CONSTRAINT fk_inasistencias_paciente
    FOREIGN KEY (paciente_id) REFERENCES pacientes(id) ON DELETE CASCADE,
  CONSTRAINT fk_inasistencias_orden
    FOREIGN KEY (orden_id) REFERENCES orden_medica(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS continuidad_tratamiento (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  paciente_id BIGINT NOT NULL,
  concepto LONGTEXT NOT NULL,
  vigencia_desde DATE NOT NULL,
  vigencia_hasta DATE NULL,
  sesiones INT UNSIGNED NOT NULL DEFAULT 0,
  creado_por VARCHAR(20) NOT NULL DEFAULT '',
  creado DATETIME(6) NOT NULL,
  CONSTRAINT fk_continuidad_paciente
    FOREIGN KEY (paciente_id) REFERENCES pacientes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS valor_tratamiento (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  paciente_id BIGINT NOT NULL,
  tipo_terapia VARCHAR(80) NOT NULL,
  valor_sesion DECIMAL(12,2) NOT NULL,
  activo TINYINT(1) NOT NULL DEFAULT 1,
  creado DATETIME(6) NOT NULL,
  CONSTRAINT fk_valor_trat_paciente
    FOREIGN KEY (paciente_id) REFERENCES pacientes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS pago (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  paciente_id BIGINT NOT NULL,
  fecha DATE NOT NULL,
  valor DECIMAL(12,2) NOT NULL,
  tipo_pago VARCHAR(40) NOT NULL DEFAULT 'EFECTIVO',
  concepto VARCHAR(200) NOT NULL DEFAULT '',
  soporte VARCHAR(100) NULL,
  registrado_por VARCHAR(20) NOT NULL DEFAULT '',
  creado DATETIME(6) NOT NULL,
  CONSTRAINT fk_pago_paciente
    FOREIGN KEY (paciente_id) REFERENCES pacientes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS factura (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  paciente_id BIGINT NOT NULL,
  fecha DATE NOT NULL,
  valor DECIMAL(12,2) NOT NULL,
  cantidad INT UNSIGNED NOT NULL DEFAULT 1,
  valor_total DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  tipo VARCHAR(40) NOT NULL DEFAULT 'SESION',
  concepto VARCHAR(120) NOT NULL DEFAULT '',
  proposito VARCHAR(12) NOT NULL DEFAULT '',
  tipo_terapia_nombre VARCHAR(80) NOT NULL DEFAULT '',
  cita_id INT UNSIGNED NULL,
  observacion LONGTEXT NOT NULL,
  es_inasistencia TINYINT(1) NOT NULL DEFAULT 0,
  anulada TINYINT(1) NOT NULL DEFAULT 0,
  anulada_en DATETIME(6) NULL,
  motivo_anulacion VARCHAR(200) NOT NULL DEFAULT '',
  creado_por VARCHAR(20) NOT NULL DEFAULT '',
  creado DATETIME(6) NOT NULL,
  KEY factura_cita_id (cita_id),
  CONSTRAINT fk_factura_paciente
    FOREIGN KEY (paciente_id) REFERENCES pacientes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS consentimientos_informados (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  terapeuta_doc VARCHAR(20) NOT NULL,
  paciente_documento VARCHAR(20) NOT NULL,
  paciente_nombre VARCHAR(200) NOT NULL DEFAULT '',
  tipo_terapia_id INT UNSIGNED NOT NULL,
  tipo_terapia_nombre VARCHAR(80) NOT NULL,
  especialidad_codigo VARCHAR(20) NOT NULL DEFAULT '',
  cita_id INT UNSIGNED NULL,
  decision VARCHAR(12) NOT NULL DEFAULT 'APROBADO',
  firmante_nombre VARCHAR(200) NOT NULL,
  firmante_documento VARCHAR(40) NOT NULL,
  firma_paciente VARCHAR(255) NOT NULL DEFAULT '',
  pdf_path VARCHAR(255) NOT NULL DEFAULT '',
  vigente TINYINT(1) NOT NULL DEFAULT 1,
  creado DATETIME(6) NOT NULL,
  KEY ci_terapeuta_doc (terapeuta_doc),
  KEY ci_paciente_documento (paciente_documento),
  KEY ci_tipo_terapia_id (tipo_terapia_id),
  KEY ci_cita_id (cita_id),
  KEY ci_vigente (vigente),
  KEY ci_creado (creado),
  KEY ci_terapeuta_paciente_tipo (terapeuta_doc, paciente_documento, tipo_terapia_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Control migraciones Django (core 0001–0009)
CREATE TABLE IF NOT EXISTS django_migrations (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  app VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL,
  applied DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT v.app, v.name, UTC_TIMESTAMP(6) FROM (
  SELECT 'core' AS app, '0001_initial' AS name UNION ALL
  SELECT 'core', '0002_clinica_ficha_valoracion' UNION ALL
  SELECT 'core', '0003_paciente_por_terapeuta' UNION ALL
  SELECT 'core', '0004_alter_paciente_id' UNION ALL
  SELECT 'core', '0005_cita_id_atencion' UNION ALL
  SELECT 'core', '0006_cuenta_cobro_campos' UNION ALL
  SELECT 'core', '0007_factura_anulacion' UNION ALL
  SELECT 'core', '0008_alter_valoracion_numero_sesiones' UNION ALL
  SELECT 'core', '0009_consentimiento_informado'
) AS v
WHERE NOT EXISTS (
  SELECT 1 FROM django_migrations dm WHERE dm.app = v.app AND dm.name = v.name
);

-- -----------------------------------------------------------------------------
-- Datos mínimos de prueba (mismo terapeuta admin@prueba.com / 10000001)
-- -----------------------------------------------------------------------------

  terapeuta_doc, documento, tipo_documento, nombres,
  primer_apellido, segundo_apellido, apellidos,
  fecha_nacimiento, sexo, telefono, email, nacionalidad,
  datos_basicos_completos, activo, creado, actualizado
)
SELECT
  '10000001', '1111', 'CC', 'Juan',
  'Pérez', 'Gómez', 'Pérez Gómez',
  '1985-05-10', 'M', '3001234567', 'juan.perez@ejemplo.com', 'Colombia',
  1, 1, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM pacientes WHERE terapeuta_doc='10000001' AND documento='1111'
);

  paciente_id, entidad, tipo_vinculacion, ocupacion, estado_civil,
  localidad, barrio, direccion, telefono, celular, email,
  acudiente, parentesco, telefono_acudiente, actualizado
)
SELECT p.id, 'Particular', 'Particular', 'Empleado', 'Soltero',
  'Bogotá', 'Centro', 'Calle 1 # 2-3', '3001234567', '3001234567', 'juan.perez@ejemplo.com',
  '', '', '', UTC_TIMESTAMP(6)
FROM pacientes p
WHERE p.terapeuta_doc='10000001' AND p.documento='1111'
  AND NOT EXISTS (SELECT 1 FROM informacion i WHERE i.paciente_id = p.id);

  paciente_id, enfermedades, traumas, cirugias, protesis, alergias,
  h_familiar, h_ocupacional, marcapasos, medicamentos, traumaticos,
  hospitalarios, otros, observaciones, diligenciado, actualizado
)
SELECT p.id, '', '', '', '', 'Ninguna conocida',
  '', '', 'NO', '', '',
  '', '', '', 0, UTC_TIMESTAMP(6)
FROM pacientes p
WHERE p.terapeuta_doc='10000001' AND p.documento='1111'
  AND NOT EXISTS (SELECT 1 FROM antecedentes a WHERE a.paciente_id = p.id);

-- Verificación
SELECT 'pacientes' AS tabla, COUNT(*) AS n FROM pacientes
UNION ALL SELECT 'informacion', COUNT(*) FROM informacion
UNION ALL SELECT 'antecedentes', COUNT(*) FROM antecedentes
UNION ALL SELECT 'valoraciones', COUNT(*) FROM valoraciones
UNION ALL SELECT 'facturas', COUNT(*) FROM factura
UNION ALL SELECT 'consentimientos', COUNT(*) FROM consentimientos_informados;


-- #############################################################################
-- Continuación consolidada desde schema_seed_parametrizacion.sql
-- #############################################################################

-- =============================================================================
-- Fisiocloud — backend_parametrizacion
-- BD + tablas + datos (= seed_parametros)
-- Uso: sudo mysql -u root -p < schema_seed_parametrizacion.sql
-- Luego (opcional): python manage.py migrate --fake
-- =============================================================================

CREATE DATABASE IF NOT EXISTS fisiocloud_parametrizacion
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

GRANT ALL PRIVILEGES ON fisiocloud_parametrizacion.* TO 'fisiocloud'@'localhost';
FLUSH PRIVILEGES;

USE fisiocloud_parametrizacion;

-- -----------------------------------------------------------------------------
-- Tablas
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS parametros_sistema (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  clave VARCHAR(80) NOT NULL UNIQUE,
  valor LONGTEXT NOT NULL,
  descripcion VARCHAR(255) NOT NULL DEFAULT ''
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tipo_doc (
  codigo VARCHAR(10) NOT NULL PRIMARY KEY,
  nombre VARCHAR(80) NOT NULL,
  activo TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tipo_vinculacion (
  nombre VARCHAR(80) NOT NULL PRIMARY KEY
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS estado_civil (
  nombre VARCHAR(40) NOT NULL PRIMARY KEY
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS nacionalidad (
  codigo VARCHAR(10) NOT NULL PRIMARY KEY,
  nombre VARCHAR(80) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS entidad (
  codigo VARCHAR(20) NOT NULL PRIMARY KEY,
  nombre VARCHAR(120) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS localidad (
  codigo VARCHAR(20) NOT NULL PRIMARY KEY,
  nombre VARCHAR(120) NOT NULL,
  activo TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS uap (
  codigo VARCHAR(20) NOT NULL PRIMARY KEY,
  nombre VARCHAR(120) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS plan_atencion (
  codigo VARCHAR(20) NOT NULL PRIMARY KEY,
  nombre VARCHAR(120) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS cups (
  id_cups VARCHAR(20) NOT NULL PRIMARY KEY,
  descripcion VARCHAR(200) NOT NULL,
  alias VARCHAR(80) NOT NULL DEFAULT '',
  activo TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS dxcie10 (
  id_dx VARCHAR(10) NOT NULL PRIMARY KEY,
  diagnostico LONGTEXT NOT NULL,
  activo TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tipo_terapia (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  nombre VARCHAR(80) NOT NULL,
  duracion_minutos INT UNSIGNED NOT NULL DEFAULT 45,
  activo TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS django_migrations (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  app VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL,
  applied DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT v.app, v.name, UTC_TIMESTAMP(6) FROM (
  SELECT 'core' AS app, '0001_initial' AS name UNION ALL
  SELECT 'core', '0002_dxcie10_activo' UNION ALL
  SELECT 'core', '0003_localidad_activo' UNION ALL
  SELECT 'core', '0004_cups_activo' UNION ALL
  SELECT 'core', '0005_tipodocumento_activo'
) AS v
WHERE NOT EXISTS (
  SELECT 1 FROM django_migrations dm WHERE dm.app=v.app AND dm.name=v.name
);

-- -----------------------------------------------------------------------------
-- Datos (= seed_parametros)
-- -----------------------------------------------------------------------------

ON DUPLICATE KEY UPDATE valor=VALUES(valor);

ON DUPLICATE KEY UPDATE nombre=VALUES(nombre), activo=1;



ON DUPLICATE KEY UPDATE nombre=VALUES(nombre);

ON DUPLICATE KEY UPDATE nombre=VALUES(nombre);

-- Tipos de terapia (IDs 1..6 alineados con seed de agendamiento.parametrizacion_id)
ON DUPLICATE KEY UPDATE
  nombre=VALUES(nombre),
  duracion_minutos=VALUES(duracion_minutos),
  activo=1;

DELETE FROM dxcie10 WHERE id_dx IN ('12', 'qwqw');

ON DUPLICATE KEY UPDATE diagnostico=VALUES(diagnostico), activo=1;

-- Verificación
SELECT 'parametros_sistema' AS tabla, COUNT(*) AS n FROM parametros_sistema
UNION ALL SELECT 'tipo_doc', COUNT(*) FROM tipo_doc
UNION ALL SELECT 'tipo_terapia', COUNT(*) FROM tipo_terapia
UNION ALL SELECT 'dxcie10', COUNT(*) FROM dxcie10
UNION ALL SELECT 'estado_civil', COUNT(*) FROM estado_civil
UNION ALL SELECT 'tipo_vinculacion', COUNT(*) FROM tipo_vinculacion;


-- #############################################################################
-- Continuación consolidada desde schema_seed_tratamiento_casa.sql
-- #############################################################################

-- =============================================================================
-- Fisiocloud — backend_tratamiento_casa
-- BD + tablas + ejercicios iniciales (= seed_ejercicios)
-- Uso: sudo mysql -u root -p < schema_seed_tratamiento_casa.sql
-- =============================================================================

CREATE DATABASE IF NOT EXISTS fisiocloud_tratamiento_casa
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

GRANT ALL PRIVILEGES ON fisiocloud_tratamiento_casa.* TO 'fisiocloud'@'localhost';
FLUSH PRIVILEGES;

USE fisiocloud_tratamiento_casa;

-- -----------------------------------------------------------------------------
-- Tablas (estado final modelos actuales)
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ejercicios (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  codigo VARCHAR(40) NOT NULL UNIQUE,
  titulo VARCHAR(150) NOT NULL,
  instrucciones LONGTEXT NOT NULL,
  imagen VARCHAR(100) NULL,
  video_url VARCHAR(500) NOT NULL DEFAULT '',
  video_archivo VARCHAR(100) NULL,
  duracion_segundos INT UNSIGNED NOT NULL DEFAULT 60,
  activo TINYINT(1) NOT NULL DEFAULT 1,
  creado DATETIME(6) NOT NULL,
  actualizado DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS plantillas_plan (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  nombre VARCHAR(150) NOT NULL,
  descripcion LONGTEXT NOT NULL,
  oficial TINYINT(1) NOT NULL DEFAULT 0,
  creado_por VARCHAR(20) NOT NULL DEFAULT '',
  creado_por_nombre VARCHAR(160) NOT NULL DEFAULT '',
  activo TINYINT(1) NOT NULL DEFAULT 1,
  creado DATETIME(6) NOT NULL,
  actualizado DATETIME(6) NOT NULL,
  KEY plantillas_oficial (oficial),
  KEY plantillas_creado_por (creado_por)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS plantilla_pasos (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  plantilla_id BIGINT NOT NULL,
  ejercicio_id BIGINT NOT NULL,
  orden SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  instrucciones_override LONGTEXT NOT NULL,
  UNIQUE KEY plantilla_pasos_orden_uniq (plantilla_id, orden),
  CONSTRAINT fk_plantilla_pasos_plantilla
    FOREIGN KEY (plantilla_id) REFERENCES plantillas_plan(id) ON DELETE CASCADE,
  CONSTRAINT fk_plantilla_pasos_ejercicio
    FOREIGN KEY (ejercicio_id) REFERENCES ejercicios(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS planes_caseros (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  paciente_documento VARCHAR(20) NOT NULL,
  paciente_nombre VARCHAR(160) NOT NULL DEFAULT '',
  paciente_email VARCHAR(254) NOT NULL DEFAULT '',
  titulo VARCHAR(150) NOT NULL,
  descripcion LONGTEXT NOT NULL,
  estado VARCHAR(20) NOT NULL DEFAULT 'BORRADOR',
  asignado_por VARCHAR(20) NOT NULL DEFAULT '',
  asignado_por_nombre VARCHAR(160) NOT NULL DEFAULT '',
  plantilla_id BIGINT NULL,
  creado DATETIME(6) NOT NULL,
  actualizado DATETIME(6) NOT NULL,
  KEY planes_caseros_paciente (paciente_documento),
  CONSTRAINT fk_planes_caseros_plantilla
    FOREIGN KEY (plantilla_id) REFERENCES plantillas_plan(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS plan_casero_pasos (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  plan_id BIGINT NOT NULL,
  ejercicio_id BIGINT NOT NULL,
  orden SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  ventana_inicio_offset_min INT UNSIGNED NOT NULL DEFAULT 0,
  ventana_duracion_min INT UNSIGNED NOT NULL DEFAULT 1440,
  instrucciones_override LONGTEXT NOT NULL,
  UNIQUE KEY plan_casero_pasos_orden_uniq (plan_id, orden),
  CONSTRAINT fk_plan_casero_pasos_plan
    FOREIGN KEY (plan_id) REFERENCES planes_caseros(id) ON DELETE CASCADE,
  CONSTRAINT fk_plan_casero_pasos_ejercicio
    FOREIGN KEY (ejercicio_id) REFERENCES ejercicios(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS accesos_token (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  token VARCHAR(64) NOT NULL UNIQUE,
  plan_id BIGINT NOT NULL,
  paciente_documento VARCHAR(20) NOT NULL,
  paciente_email VARCHAR(254) NOT NULL DEFAULT '',
  paciente_nombre VARCHAR(160) NOT NULL DEFAULT '',
  valido_desde DATETIME(6) NOT NULL,
  valido_hasta DATETIME(6) NOT NULL,
  max_clicks INT UNSIGNED NOT NULL DEFAULT 5,
  clicks_usados INT UNSIGNED NOT NULL DEFAULT 0,
  usado TINYINT(1) NOT NULL DEFAULT 0,
  creado_por VARCHAR(20) NOT NULL DEFAULT '',
  creado DATETIME(6) NOT NULL,
  KEY accesos_token_token (token),
  CONSTRAINT fk_accesos_token_plan
    FOREIGN KEY (plan_id) REFERENCES planes_caseros(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS confirmacion_terapias (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  paciente_documento VARCHAR(20) NOT NULL,
  fecha DATE NOT NULL,
  tipo_terapia VARCHAR(80) NOT NULL DEFAULT '',
  confirmado TINYINT(1) NOT NULL DEFAULT 1,
  observaciones LONGTEXT NOT NULL,
  soporte VARCHAR(100) NULL,
  registrado_por VARCHAR(20) NOT NULL DEFAULT '',
  creado DATETIME(6) NOT NULL,
  KEY confirmacion_paciente (paciente_documento)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS django_migrations (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  app VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL,
  applied DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT v.app, v.name, UTC_TIMESTAMP(6) FROM (
  SELECT 'core' AS app, '0001_initial' AS name UNION ALL
  SELECT 'core', '0002_plantillaplan_alter_accesotoken_options_and_more' UNION ALL
  SELECT 'core', '0003_alter_plantillaplan_options_ejercicio_imagen_and_more'
) AS v
WHERE NOT EXISTS (
  SELECT 1 FROM django_migrations dm WHERE dm.app=v.app AND dm.name=v.name
);

