-- =============================================================================
-- Fisiocloud — backend_soporte
-- BD + tablas (tickets / mensajes)
-- No hay seed de negocio: los tickets se crean desde la app.
-- Uso: sudo mysql -u root -p < schema_seed_soporte.sql
-- =============================================================================

CREATE DATABASE IF NOT EXISTS fisiocloud_soporte
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

GRANT ALL PRIVILEGES ON fisiocloud_soporte.* TO 'fisiocloud'@'localhost';
FLUSH PRIVILEGES;

USE fisiocloud_soporte;

CREATE TABLE IF NOT EXISTS soporte_tickets (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  numero INT UNSIGNED NOT NULL,
  asunto VARCHAR(200) NOT NULL,
  usuario_doc VARCHAR(20) NOT NULL,
  usuario_email VARCHAR(254) NOT NULL DEFAULT '',
  usuario_nombre VARCHAR(160) NOT NULL DEFAULT '',
  estado VARCHAR(20) NOT NULL DEFAULT 'ABIERTO',
  asignado_admin_doc VARCHAR(20) NOT NULL DEFAULT '',
  asignado_admin_nombre VARCHAR(160) NOT NULL DEFAULT '',
  ultimo_mensaje_en DATETIME(6) NULL,
  cerrado_en DATETIME(6) NULL,
  cerrado_por VARCHAR(20) NOT NULL DEFAULT '',
  creado DATETIME(6) NOT NULL,
  actualizado DATETIME(6) NOT NULL,
  UNIQUE KEY soporte_tickets_numero_uniq (numero),
  KEY soporte_tickets_numero (numero),
  KEY soporte_tickets_usuario_doc (usuario_doc),
  KEY soporte_tickets_estado (estado)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS soporte_mensajes (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  ticket_id BIGINT NOT NULL,
  autor_doc VARCHAR(20) NOT NULL DEFAULT '',
  autor_nombre VARCHAR(160) NOT NULL DEFAULT '',
  autor_rol VARCHAR(12) NOT NULL DEFAULT 'USER',
  cuerpo LONGTEXT NOT NULL,
  imagen VARCHAR(100) NULL,
  creado DATETIME(6) NOT NULL,
  CONSTRAINT fk_soporte_mensajes_ticket
    FOREIGN KEY (ticket_id) REFERENCES soporte_tickets(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS django_migrations (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  app VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL,
  applied DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT 'core', '0001_initial', UTC_TIMESTAMP(6)
WHERE NOT EXISTS (
  SELECT 1 FROM django_migrations WHERE app='core' AND name='0001_initial'
);

-- Verificación
SELECT 'soporte_tickets' AS tabla, COUNT(*) AS n FROM soporte_tickets
UNION ALL SELECT 'soporte_mensajes', COUNT(*) FROM soporte_mensajes;


