-- =============================================================================
-- Fisiocloud — backend_procesos_automaticos
-- BD + tablas (preferencias / logs / ejecuciones de jobs)
-- No hay seed de negocio: preferencias y logs se crean en runtime.
-- Códigos de proceso: recordatorio_agenda, envio_hc_fin
-- Uso: sudo mysql -u root -p < schema_seed_procesos_automaticos.sql
-- =============================================================================

CREATE DATABASE IF NOT EXISTS fisiocloud_procesos_automaticos
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

GRANT ALL PRIVILEGES ON fisiocloud_procesos_automaticos.* TO 'fisiocloud'@'localhost';
FLUSH PRIVILEGES;

USE fisiocloud_procesos_automaticos;

CREATE TABLE IF NOT EXISTS preferencias_proceso (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  terapeuta_doc VARCHAR(20) NOT NULL,
  proceso_codigo VARCHAR(40) NOT NULL,
  habilitado TINYINT(1) NOT NULL DEFAULT 1,
  creado DATETIME(6) NOT NULL,
  actualizado DATETIME(6) NOT NULL,
  UNIQUE KEY preferencias_proceso_terapeuta_doc_proceso_codigo_uniq (terapeuta_doc, proceso_codigo),
  KEY preferencias_proceso_terapeuta_doc (terapeuta_doc),
  KEY preferencias_proceso_proceso_codigo (proceso_codigo)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS logs_proceso (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  proceso_codigo VARCHAR(40) NOT NULL,
  terapeuta_doc VARCHAR(20) NOT NULL DEFAULT '',
  paciente_doc VARCHAR(20) NOT NULL DEFAULT '',
  paciente_email VARCHAR(254) NOT NULL DEFAULT '',
  referencia VARCHAR(120) NOT NULL DEFAULT '',
  estado VARCHAR(10) NOT NULL DEFAULT 'OK',
  detalle LONGTEXT NOT NULL,
  creado DATETIME(6) NOT NULL,
  KEY logs_proceso_proceso_codigo (proceso_codigo),
  KEY logs_proceso_terapeuta_doc (terapeuta_doc),
  KEY logs_proceso_creado (creado)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS ejecuciones_job (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  proceso_codigo VARCHAR(40) NOT NULL,
  iniciado DATETIME(6) NOT NULL,
  finalizado DATETIME(6) NULL,
  ok TINYINT(1) NOT NULL DEFAULT 1,
  procesados INT UNSIGNED NOT NULL DEFAULT 0,
  enviados INT UNSIGNED NOT NULL DEFAULT 0,
  omitidos INT UNSIGNED NOT NULL DEFAULT 0,
  errores INT UNSIGNED NOT NULL DEFAULT 0,
  detalle LONGTEXT NOT NULL,
  KEY ejecuciones_job_proceso_codigo (proceso_codigo)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS django_migrations (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  app VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL,
  applied DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT 'core', '0001_initial', UTC_TIMESTAMP(6)
WHERE NOT EXISTS (
  SELECT 1 FROM django_migrations WHERE app='core' AND name='0001_initial'
);

-- Verificación
SELECT 'preferencias_proceso' AS tabla, COUNT(*) AS n FROM preferencias_proceso
UNION ALL SELECT 'logs_proceso', COUNT(*) FROM logs_proceso
UNION ALL SELECT 'ejecuciones_job', COUNT(*) FROM ejecuciones_job;


-- #############################################################################
-- Continuación consolidada desde schema_seed_asistente_voz.sql
-- #############################################################################

-- =============================================================================
-- Fisiocloud — backend_asistente_voz
-- BD + tablas (sesiones de valoración por voz / respuestas)
-- No hay seed de negocio: las sesiones se crean desde la app.
-- status: in_progress | completed | cancelled | applied
-- Uso: sudo mysql -u root -p < schema_seed_asistente_voz.sql
-- =============================================================================

CREATE DATABASE IF NOT EXISTS fisiocloud_asistente_voz
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

GRANT ALL PRIVILEGES ON fisiocloud_asistente_voz.* TO 'fisiocloud'@'localhost';
FLUSH PRIVILEGES;

USE fisiocloud_asistente_voz;

CREATE TABLE IF NOT EXISTS voice_sessions (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  terapeuta_doc VARCHAR(20) NOT NULL,
  paciente_documento VARCHAR(20) NOT NULL,
  paciente_nombre VARCHAR(200) NOT NULL DEFAULT '',
  tipo_valoracion VARCHAR(20) NOT NULL,
  cita_id INT UNSIGNED NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'in_progress',
  current_step INT UNSIGNED NOT NULL DEFAULT 0,
  current_question VARCHAR(255) NOT NULL DEFAULT '',
  script JSON NOT NULL,
  meta JSON NOT NULL,
  valoracion_id INT UNSIGNED NULL,
  summary LONGTEXT NOT NULL,
  creado DATETIME(6) NOT NULL,
  completed_at DATETIME(6) NULL,
  KEY voice_sessions_terapeuta_doc (terapeuta_doc),
  KEY voice_sessions_paciente_documento (paciente_documento),
  KEY voice_sessions_tipo_valoracion (tipo_valoracion),
  KEY voice_sessions_cita_id (cita_id),
  KEY voice_sessions_status (status),
  KEY voice_sessions_creado (creado)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS voice_answers (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  session_id BIGINT NOT NULL,
  question_key VARCHAR(80) NOT NULL,
  question_text VARCHAR(255) NOT NULL,
  answer_text LONGTEXT NOT NULL,
  order_index INT UNSIGNED NOT NULL DEFAULT 0,
  CONSTRAINT fk_voice_answers_session
    FOREIGN KEY (session_id) REFERENCES voice_sessions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS django_migrations (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  app VARCHAR(255) NOT NULL,
  name VARCHAR(255) NOT NULL,
  applied DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT 'core', '0001_initial', UTC_TIMESTAMP(6)
WHERE NOT EXISTS (
  SELECT 1 FROM django_migrations WHERE app='core' AND name='0001_initial'
);

-- Verificación
SELECT 'voice_sessions' AS tabla, COUNT(*) AS n FROM voice_sessions
UNION ALL SELECT 'voice_answers', COUNT(*) FROM voice_answers;



